local vehicle_class <const> = {
    [0] = 'COMPACT',        -- Compacts
    [1] = 'SEDAN',          -- Sedans
    [2] = 'SUV',            -- SUVs
    [3] = 'COUPE',          -- Coupes
    [4] = 'MUSCLE',         -- Muscle
    [5] = 'SPORT_CLASSIC',  -- Sports Classics
    [6] = 'SPORT',          -- Sports
    [7] = 'SUPER',          -- Super
    [8] = 'MOTORCYCLE',     -- Motorcycles
    [9] = 'OFF_ROAD',       -- Off-road
    [10] = 'INDUSTRIAL',    -- Industrial
    [11] = 'UTILITY',       -- Utility
    [12] = 'VAN',           -- Vans
    [13] = 'CYCLE',         -- Cycles
    [14] = 'BOAT',          -- Boats
    [15] = 'HELICOPTER',    -- Helicopters
    [16] = 'PLANE',         -- Planes
    [17] = 'SERVICE',       -- Service
    [18] = 'EMERGENCY',     -- Emergency
    [19] = 'MILITARY',      -- Military
    [20] = 'COMMERCIAL',    -- Commercial
    [21] = 'RAIL',          -- Trains
    [22] = 'OPEN_WHEEL'
}

local function GetByModel(model)
    if type(model) == "string" then model = joaat(model) end
    return VEHICLES[model]
end

local function GetVehiclesByClassName(classIdOrName)
    
    if type(classIdOrName) == 'number' then
        classIdOrName = vehicle_class[classIdOrName]
        if not classIdOrName then return {} end
    end

    classIdOrName = classIdOrName:upper()

    --check if is a valid class
    local is_valid_class = false

    for _, v in next, vehicle_class do
        if v == classIdOrName then
            is_valid_class = true
            break
        end
    end

    if not is_valid_class then return {} end


    local d = {}
    for _, v in next, VEHICLES or {} do
        if v.Class == classIdOrName then
            d[#d + 1] = v
        end
    end
    return d
end

local function GetVehiclesByType(vehType)
    if not vehType then return {} end
    vehType = vehType:upper()
    local d = {}
    for _, v in next, VEHICLES or {} do
        if v.Type == vehType then
            d[#d + 1] = v
        end
    end
    return d
end

return {
    list = VEHICLES,
    GetByModel = GetByModel,
    GetVehiclesByClassName = GetVehiclesByClassName,
    GetVehiclesByType = GetVehiclesByType,
}
